node -e "const { MongoClient } = require('mongodb'); (async () => { const local = new MongoClient(process.env.LOCAL_MONGODB_URI, { serverSelectionTimeoutMS: 20000 }); const atlas = new MongoClient(process.env.MONGODB_URI, { serverSelectionTimeoutMS: 20000 }); try { await local.connect(); await atlas.connect(); const localDb = local.db(); const atlasDb = atlas.db(); const cols = await localDb.listCollections().toArray(); console.log('LOCAL_COLLECTIONS=' + cols.map(c => c.name).join(',')); for (const c of cols) { const docs = await localDb.collection(c.name).find({}).toArray(); console.log('COPYING ' + c.name + ': ' + docs.length + ' docs'); const target = atlasDb.collection(c.name); await target.deleteMany({}); if (docs.length > 0) { await target.insertMany(docs, { ordered: false }); } const count = await target.countDocuments(); console.log('ATLAS_' + c.name + '=' + count); } console.log('MIGRATION_COMPLETE'); } catch (e) { console.error('ERROR=' + (e && e.message ? e.message : String(e))); process.exit(1); } finally { await local.close(); await atlas.close(); } })();"
